const FLOOR_LEVELS = ['Basement', 'Ground Floor', 'First Floor', 'Second Floor', 'Third Floor'];
const STAIRCASE_NUMBERS = ['1', '2'];
const APARTMENT_UNITS = ['1A', '1B', '2A', '2B', '3A', '3B'];
const DIRECTIONS = ['East Side', 'West Side', 'North Side', 'South Side'];
const createWorkType = (work_type, work_names) => ({
    work_type,
    work_names,
});
const createPrefixedWorkType = (work_type, prefixes, suffix = work_type) => ({
    work_type,
    work_names: prefixes.map((prefix) => `${prefix} ${suffix}`),
});
const buildStaircasePartitionPrefixes = () => {
    const prefixes = [];
    FLOOR_LEVELS.slice(1).forEach((floor) => {
        STAIRCASE_NUMBERS.forEach((staircase) => {
            prefixes.push(`Staircase ${staircase} ${floor}`);
        });
    });
    return prefixes;
};
const buildStaircasePrefixes = () => {
    const prefixes = [];
    FLOOR_LEVELS.slice(1).forEach((floor) => {
        STAIRCASE_NUMBERS.forEach((staircase) => {
            prefixes.push(`Staircase ${staircase} ${floor}`);
        });
    });
    return prefixes;
};
const buildLiftPrefixes = () => {
    const prefixes = [];
    FLOOR_LEVELS.slice(1).forEach((floor) => {
        STAIRCASE_NUMBERS.forEach((lift) => {
            prefixes.push(`Lift ${lift} ${floor}`);
        });
    });
    return prefixes;
};
